{{ $('Start').first().json.job_posting_wrapped }}

Classify every segment now.

parameters.inputSchema:
 {
  "type": "object",
  "properties": {
    "role_signal": {
      "type": "string",
      "description": "One sentence: what this role most needs from a candidate CV."
    },
    "project_order": {
      "type": "array",
      "items": { "type": "string" },
      "description": "All project titles from CV ordered by relevance to this role, most relevant first. Use exact titles as they appear in the CV."
    },
    "segments": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "Unique slug. Examples: profile_summary, seace_bullet_1, pdf_bullet_2, skills_data_engineering, skills_frontend"
          },
          "segment_type": {
            "type": "string",
            "enum": ["profile_summary", "bullet", "skills_subcategory"]
          },
          "original": {
            "type": "string",
            "description": "Exact verbatim text of this segment as it appears in the CV. Must be copy-pasteable."
          },
          "classification": {
            "type": "string",
            "enum": ["DIREKT", "TRANSFERABEL", "DISTRAKTOR"]
          },
          "action": {
            "type": "string",
            "enum": ["KEEP", "REPLACE", "SHORTEN", "REMOVE"]
          },
          "reasoning": {
            "type": "string",
            "description": "Max 12 words explaining the classification."
          },
          "priority_rank": {
            "type": "integer",
            "description": "1 = most relevant to this role."
          },
          "priority_score": { 
            "type": "number", 
            "description": "0.0–1.0 relevance score." 
          },
          "output_word_budget": { 
            "type": "integer", 
            "description": "Target word count after editing. 0 if REMOVE." 
          },
          "output_word_max": { 
            "type": "integer", 
            "description": "Hard ceiling. output_word_budget × 1.2. 0 if REMOVE." 
          }
        },
        "required": ["id", "segment_type", "original", "classification", "action", "reasoning", "priority_rank", "priority_score", "output_word_budget", "output_word_max"]
      }
    }
  },
  "required": ["role_signal", "project_order", "segments"]
}

parameters.jsCode:
const data = $('Classifier').first().json.output;
const segments = data.segments;
const projectOrder = data.project_order;
const roleSignal = data.role_signal;

// Enforce action rules deterministically
const enforced = segments.map(seg => {
  let finalAction = seg.action;

  // Rule 1: DISTRAKTOR -> always REMOVE
  if (seg.classification === 'DISTRAKTOR') {
    finalAction = 'REMOVE';
  }

  // Rule 2: TRANSFERABEL -> never REMOVE, downgrade to SHORTEN
  if (seg.classification === 'TRANSFERABEL' && seg.action === 'REMOVE') {
    finalAction = 'SHORTEN';
    // Recompute budget — was 0 because Classifier intended REMOVE
    const wc = (seg.original || '').trim().split(/\s+/).filter(Boolean).length;
    seg.output_word_budget = Math.max(10, Math.floor(wc * 0.50));
    seg.output_word_max = Math.max(12, Math.floor(wc * 0.55));
  }

  // Rule 3: KEEP with no change needed -> mark as skip
  if (finalAction === 'KEEP') {
    finalAction = 'SKIP';
  }

  return { ...seg, finalAction };
});

// Deterministic override: TRANSFERABEL segments ≥25 words that survived as SKIP must be SHORTEN.
// Haiku may not reliably apply the word-count rule; this guarantees compression.
for (const seg of enforced) {
  if (seg.classification === 'TRANSFERABEL' && seg.finalAction === 'SKIP') {
    const wordCount = (seg.original || '').trim().split(/\s+/).filter(Boolean).length;
    if (wordCount >= 25) {
      seg.finalAction = 'SHORTEN';
      seg.output_word_budget = Math.max(20, Math.floor(wordCount * 0.50));
      seg.output_word_max = Math.max(25, Math.floor(wordCount * 0.55));
      seg.reasoning = 'Segment over word-count threshold. Compress to core transferable evidence only. Remove enumerated lists of named tools, frameworks, or algorithms not present in the job posting.';
    }
  }
  if (seg.classification === 'DIREKT' && seg.finalAction === 'SKIP') {
    const wordCount = (seg.original || '').trim().split(/\s+/).filter(Boolean).length;
    if (wordCount >= 40) {
      seg.finalAction = 'SHORTEN';
      seg.output_word_budget = Math.max(25, Math.floor(wordCount * 0.55));
      seg.output_word_max = Math.max(30, Math.floor(wordCount * 0.60));
      seg.reasoning = 'DIREKT segment over word-count threshold. Preserve core evidence; remove enumerated lists of specific named items not essential for role match.';
    }
  }
}

// Separate segments that need instructions from those that don't
const toEdit = enforced.filter(s => s.finalAction !== 'SKIP');
const toSkip = enforced.filter(s => s.finalAction === 'SKIP');

// Build the constraint block for the Generator
const constraintLines = toEdit.map(s => {
  const preview = s.original.length > 80 
    ? s.original.substring(0, 80) + '...' 
    : s.original;
  const actualWordCount = s.output_word_budget > 0
    ? (s.original || '').trim().split(/\s+/).filter(Boolean).length
    : 0;
  return `[${s.finalAction}] ${s.id} (${s.classification}) — REWRITE to ≤${s.output_word_max} words\nOriginal (${actualWordCount} words): "${preview}"\nReason: ${s.reasoning}`;
}).join('\n\n');

// Build project reorder instructions
const reorderInstructions = projectOrder
  .map((title, i) => `${i + 1}. ${title}`)
  .join('\n');

// Budget validation
const target = $('Compute Word Budget').first().json.target_words;
const TOLERANCE = 0.10;

const totalBudgeted = enforced.reduce((sum, seg) => {
  if (seg.finalAction === 'REMOVE') {
    return sum;
  }
  if (seg.finalAction === 'SKIP') {
    return sum + (seg.output_word_budget || (seg.original || '').trim().split(/\s+/).filter(Boolean).length);
  }
  return sum + (seg.output_word_budget || 0);
}, 0);

const withinTolerance = totalBudgeted >= target * (1 - TOLERANCE) && totalBudgeted <= target * (1 + TOLERANCE);

return [{
  json: {
    role_signal: roleSignal,
    project_order: projectOrder,
    reorder_instructions: reorderInstructions,
    segments_to_edit: toEdit,
    segments_to_skip: toSkip,
    constraint_block: constraintLines,
    edit_count: toEdit.length,
    budget_validation: {
      total_budgeted_words: totalBudgeted,
      target_words: target,
      within_tolerance: withinTolerance,
      delta: totalBudgeted - target
    }
  }
}];

const items = $('Cleanup Answer').first().json.output.cv_anpassungen;
const classifiedSegments = $('Enforcer').first().json.segments_to_edit;

// Build lookup: original text → classification
const classMap = {};
for (const seg of classifiedSegments) {
  classMap[seg.original.trim()] = {
    classification: seg.classification,
    finalAction: seg.finalAction
  };
}

// Keyword preservation helpers.
// Source: muss_kriterien (structured) + "nice to have" lines only.
// Excludes responsibilities prose to prevent false positives on generic terms.
const STOP_WORDS = new Set([
  'with','that','this','from','have','will','your','their','they','been',
  'were','also','when','what','which','into','more','some','such','than',
  'then','them','these','those','each','both','very','just','only','over',
  'well','even','most','many','much','about','after','before','between',
  'during','through','within','without','across','against','along','among',
  'around','behind','below','beside','beyond','since','until','upon','while',
  'where','there','here','like','make','made','work','team','role','good',
  'able','need','want','take','give','know','find','look','come','back',
  'used','using','uses','our','its','for','the','and','not','are','all',
  'can','has','had','was','been','may','new','own','use','per','via',
  'und','die','der','das','ist','mit','für','auf','ein','wie','was',
  'hat','war','bei','aus','vom','den','dem','des','bin','wir','ihr',
  'sie','ihm','ihn','uns','dir','ich','wer','man','nur','aber','auch',
  'noch','sich','nach','über','mehr','zum','zur','beim','oder','nicht',
  'sind','wird','eine','einen','einem','einer','alle','werden',
  'kann','sein','haben','dass','dies','wenn','dann','ihre',
  'ihren','ihrer','ihres','dieses','diese','dieser','diesen','diesem',
  'solche','solch','solcher','keine','kein','keiner','keinem','keinen',
  'jede','jeden','jeder','jedem','jedes','andere','anderen','anderer',
  'anderem','viele','vielen','vieler','vielem','durch','ohne'
]);

function extractKeywords(text) {
  return (text || '')
    .split(/[\s,;:.!?()[\]{}"\'\\+\-=<>|&]+/)
    .map(t => t.trim())
    .filter(t => t.length >= 3 && !STOP_WORDS.has(t.toLowerCase()))
    .map(t => t.toLowerCase());
}

const mussText = ($('Start').first().json.muss_kriterien || []).join(' ');
const wunschText = ($('Start').first().json.wunsch_kriterien || []).join(' ');
const jobKeywords = new Set(extractKeywords(mussText + ' ' + wunschText));

function keywordViolations(original, neu) {
  const origTokens = new Set(extractKeywords(original));
  const neuTokens = new Set(extractKeywords(neu || ''));
  const violations = [];
  for (const kw of origTokens) {
    if (jobKeywords.has(kw) && !neuTokens.has(kw)) {
      violations.push(kw);
    }
  }
  return violations;
}

const valid = [];
const flagged = [];

for (const item of items) {
  // drop "// X -> Y words"
  if (item.neu) {
    item.neu = item.neu.replace(/^\/\/[^\n]*\n?/, '').trim();
  }

  // KÜRZEN with no neu field
  if (item.aktion === 'KÜRZEN' && (!item.neu || item.neu.trim() === '')) {
    continue;
  }

  // 1. No-op detection: ERSETZEN/KÜRZEN with identical text
  if (
    (item.aktion === 'ERSETZEN' || item.aktion === 'KÜRZEN') &&
    item.original.trim() === item.neu.trim()
  ) {
    // Drop silently — no instruction needed
    continue;
  }

  // 2. ENTFERNEN on TRANSFERABEL segment → flag for correction
  const lookup = classMap[item.original.trim()];
  if (
    item.aktion === 'ENTFERNEN' &&
    lookup &&
    lookup.classification === 'TRANSFERABEL'
  ) {
    flagged.push({
      ...item,
      error: 'ENTFERNEN on TRANSFERABEL segment',
      corrected_action: 'KÜRZEN'
    });
    continue;
  }

  // 3. ERSETZEN on DISTRAKTOR (should be ENTFERNEN) → correct silently
  if (
    item.aktion === 'ERSETZEN' &&
    lookup &&
    lookup.classification === 'DISTRAKTOR' &&
    item.neu !== ''
  ) {
    valid.push({ ...item, aktion: 'ENTFERNEN', neu: '' });
    continue;
  }

  // 4. Keyword preservation guard: KÜRZEN, ERSETZEN, and ENTFERNEN must not drop
  //    keywords from muss_kriterien or nice-to-have section of the job posting.
  //    For ENTFERNEN, neu is empty — any keyword in original is a violation.
  if (
    (item.aktion === 'KÜRZEN' || item.aktion === 'ERSETZEN' || item.aktion === 'ENTFERNEN') &&
    item.original
  ) {
    const missing = keywordViolations(item.original, item.neu || '');
    if (missing.length > 0) {
      flagged.push({
        ...item,
        error: `Keyword preservation violation: job-posting keywords dropped: ${missing.join(', ')}`,
        corrected_action: item.aktion
      });
      continue;
    }
  }

  valid.push(item);
}

// Cluster guard: cap ENTFERNEN at 2 per bereich to prevent entire sections being removed.
const entfernenByBereich = {};
const validAfterCluster = [];
for (const item of valid) {
  if (item.aktion === 'ENTFERNEN') {
    const b = item.bereich || '_unset';
    entfernenByBereich[b] = (entfernenByBereich[b] || 0) + 1;
    if (entfernenByBereich[b] > 2) {
      flagged.push({
        ...item,
        error: `Cluster guard: more than 2 ENTFERNEN in bereich "${b}" — converting to KÜRZEN`,
        corrected_action: 'KÜRZEN'
      });
      continue;
    }
  }
  validAfterCluster.push(item);
}

const hasErrors = flagged.length > 0;

return [{
  json: {
    output: { cv_anpassungen: validAfterCluster },
    flagged,
    has_errors: hasErrors,
    valid_count: validAfterCluster.length,
    flagged_count: flagged.length
  }
}];

parameters.text:
=Role signal: {{ $('Enforcer').first().json.role_signal }}

Required project order (generate VORNE STELLEN instructions for 
the top 2 most relevant projects):
{{ $('Enforcer').first().json.reorder_instructions }}

CLASSIFICATION DECISIONS — FINAL, DO NOT OVERRIDE:
{{ $('Enforcer').first().json.constraint_block }}

Job context:
Role: {{ $('Start').first().json.role_title }}
Must-criteria: 
{{ $('Start').first().json.muss_kriterien.map(r => '- ' + r).join('\n') }}
Highlights (use as primary evidence anchors in rewritten text):
{{ $('Start').first().json.highlights.map(h => '- ' + h).join('\n') }}
Gaps (do not invent experience to cover these):
{{ $('Start').first().json.gaps.map(g => '- ' + g).join('\n') }}

Generate cv_anpassungen now. Include:
1. VORNE STELLEN instructions for the top 2 projects in required order
2. One instruction per segment listed in CLASSIFICATION DECISIONS
   matching exactly its assigned action
3. No instructions for segments not listed above

parameters.jsCode:
let validItems = [];
let retryCorrected = [];

try {
  validItems = $('Validator').first().json.output.cv_anpassungen || [];
} catch(e) {}

try {
  retryCorrected = $('Retry LLM').first().json.output.cv_anpassungen || [];
} catch(e) {}

// Merge: valid items + corrected items
const final = [...validItems, ...retryCorrected];

return [{
  json: {
    output: {
      cv_anpassungen: final
    }
  }
}];

const cvText = $("Start").first().json.cv_text_final;

// Same cleanWordCount as in Deterministic Metrics
function cleanWordCount(text) {
  return text
    .replace(/#+\s/g, '')
    .replace(/\*\*/g, '')
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
    .replace(/^[-·]\s*/gm, '')
    .trim()
    .split(/\s+/)
    .filter(Boolean).length;
}

const words = cleanWordCount(cvText);

// If the CV is already below the desired minimum, there is nothing to cut.
// Target = 80% of the current word count, but only if the CV exceeds 700 words.
// For short CVs, the target IS the current word count (without compression).
const TARGET = words > 700
  ? Math.min(Math.max(Math.floor(words * 0.80), 700), 950)
  : words;

return [{
  json: {
    cv_word_count: words,
    target_words: TARGET,
    words_to_cut: Math.max(0, words - TARGET),
    overage_pct: Math.round(((words - TARGET) / TARGET) * 100),
    budget_tight: words > TARGET * 1.05
  }
}];

const raw = $('Generator').first().json.text || '';

// Strip markdown code fences
let cleaned = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

// Replace literal control characters inside JSON strings
// Tab → \t, carriage return → \r, etc.
cleaned = cleaned.replace(/[\t]/g, '\\t');
cleaned = cleaned.replace(/[\r]/g, '\\r');
// Literal newlines inside strings are also invalid — but we need
// to preserve structural newlines between JSON fields, so only
// replace newlines that appear inside quoted strings
cleaned = cleaned.replace(/"((?:[^"\\]|\\.)*)"/g, (match) => {
  return match.replace(/\n/g, '\\n');
});

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch(e) {
  throw new Error(`Generator JSON parse failed: ${e.message}\n\nRaw output:\n${raw.substring(0, 500)}`);
}

// Validate expected structure
if (!parsed.cv_anpassungen || !Array.isArray(parsed.cv_anpassungen)) {
  throw new Error('Generator output missing cv_anpassungen array');
}

return [{ json: { output: parsed } }];
